@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--bg:#0a0c12;--panel:#11141d;--line:#232735;--muted:#777d91;--white:#f4f3f5;--lime:#d5ff3f;--violet:#a887ff;--pink:#ff598f;font-family:'Space Grotesk',sans-serif;color:var(--white);font-synthesis:none}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg)}body{background:radial-gradient(ellipse at 70% 36%,#171526 0%,#0a0c12 50%);user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit;cursor:pointer}#app{position:relative;width:100%;height:100dvh;min-height:520px;overflow:hidden;padding:0 6.1vw}.topbar{height:82px;border-bottom:1px solid #ffffff12;display:flex;justify-content:space-between;align-items:center;position:relative;z-index:10}.brand{border:0;background:none;display:flex;gap:11px;align-items:center;font-size:17px;font-weight:700;letter-spacing:1.9px;padding:0}.brand-mark{color:var(--lime);font-size:23px}.brand-light{font-weight:400;color:#9295a4}.top-right{display:flex;align-items:center;gap:24px}.currency{display:grid;grid-template-columns:18px auto;grid-template-rows:16px 10px;column-gap:8px;align-items:center}.coin-icon{grid-row:1/3;color:var(--lime);font-size:20px;text-shadow:0 0 15px #d5ff3f55}.currency strong{font:500 14px 'DM Mono',monospace}.currency small{font:9px 'DM Mono',monospace;color:#727789;letter-spacing:1px}.icon-btn{width:34px;height:34px;border:1px solid #ffffff1c;background:#ffffff06;border-radius:50%;font-size:16px;color:#9295a4}.screen{position:absolute;top:82px;bottom:48px;left:6.1vw;right:6.1vw}.hidden{display:none!important}.home-screen{display:grid;grid-template-columns:1fr 1.05fr;grid-template-rows:1fr auto;align-items:center}.home-copy{position:relative;z-index:2;padding:25px 0 10px}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.6px;color:#9da1b1}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--lime);margin-right:7px;box-shadow:0 0 10px var(--lime)}h1{font-size:clamp(62px,8.8vw,125px);line-height:.81;letter-spacing:-.085em;margin:28px 0 22px;font-weight:700}h1 span,h2 span{color:var(--lime)}.lead{color:#989bab;font-size:15px;letter-spacing:.1px;margin:0 0 31px}.home-actions{display:flex;align-items:center;gap:24px}.primary-btn{position:relative;border:0;background:var(--lime);color:#12150b;padding:16px 23px;font:700 12px 'DM Mono',monospace;letter-spacing:1.2px;box-shadow:0 7px 30px #d5ff3f17;transition:transform .15s,filter .15s}.primary-btn:hover{transform:translateY(-2px);filter:brightness(1.08)}.primary-btn>span:first-child{margin-right:10px}.button-arrow{margin-left:26px;font-size:16px}.text-btn{border:0;background:none;color:#b9bbca;font:10px 'DM Mono',monospace;letter-spacing:1.1px;padding:12px 0}.text-btn:hover{color:var(--lime)}.best-run{margin-top:54px;border-top:1px solid #ffffff19;width:365px;display:flex;align-items:center;gap:14px;padding-top:16px}.best-icon{font-size:24px;color:var(--violet)}.best-run>div:not(.best-divider){display:grid;gap:5px}.best-run small{font:9px 'DM Mono',monospace;color:#73798b;letter-spacing:1px}.best-run strong{font:500 14px 'DM Mono',monospace}.best-divider{height:30px;width:1px;background:#ffffff22;margin:0 12px}.hero-art{position:relative;height:min(63vh,510px);min-height:340px;overflow:hidden;isolation:isolate}.hero-art:before{content:'';position:absolute;inset:10%;border-radius:50%;background:radial-gradient(circle,#9b72ff1c 0%,#5138a31c 30%,transparent 68%);filter:blur(20px)}.hero-art:after{content:'';position:absolute;inset:0;background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff08 1px,transparent 1px);background-size:45px 45px;opacity:.3;mask-image:radial-gradient(ellipse,#000 20%,transparent 75%)}.orbit{position:absolute;border:1px solid #b99bff36;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-24deg)}.orbit-a{width:71%;height:38%;box-shadow:0 0 35px #9874ff12}.orbit-b{width:58%;height:72%;transform:translate(-50%,-50%) rotate(54deg);border-color:#d5ff3f35}.orbit-c{width:91%;height:54%;transform:translate(-50%,-50%) rotate(18deg);border-color:#b99bff18}.hero-core{position:absolute;left:50%;top:50%;width:112px;height:112px;transform:translate(-50%,-50%);border-radius:50%;border:1px solid #c1a8ff91;background:radial-gradient(circle at 38% 36%,#e0d2ff 0,#af89ff 8%,#613fa5 25%,#20172d 61%,#0e111a 72%);box-shadow:0 0 18px #b58aff91,0 0 85px #946aff45,inset 0 0 26px #e4d7ff70;z-index:2}.hero-core:before,.hero-core:after{content:'';position:absolute;border-radius:50%;inset:-14px;border:1px solid #dbcdff52}.hero-core:after{inset:-31px;border-color:#d4ff3f44;border-style:dashed;animation:rotate 24s linear infinite}.core-spark{color:#f5edff;text-align:center;padding-top:42px;text-shadow:0 0 18px white;font-size:27px}.hero-label{position:absolute;font:9px 'DM Mono',monospace;color:#a6a4ba;letter-spacing:1.2px;z-index:3}.label-a{top:16%;left:17%}.label-b{right:11%;bottom:21%;color:var(--lime)}.hero-stats{position:absolute;left:10%;bottom:12%;display:grid;gap:5px;z-index:3}.hero-stats span{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#a1a3b2}.hero-stats i{display:inline-block;background:var(--lime);width:5px;height:5px;border-radius:50%;margin-right:6px}.hero-stats b{font:24px 'DM Mono',monospace;color:var(--lime)}.hero-stats small{font:8px 'DM Mono',monospace;color:#666b7d;letter-spacing:1px}.hero-radar{position:absolute;right:10%;top:12%;height:59px;width:59px;border:1px solid #ffffff21;border-radius:50%;z-index:2}.hero-radar:before,.hero-radar:after{content:'';position:absolute;background:#ffffff20}.hero-radar:before{width:1px;height:100%;left:50%}.hero-radar:after{height:1px;width:100%;top:50%}.home-bottom{grid-column:1/3;border-top:1px solid #ffffff16;height:58px;display:flex;align-items:center;gap:28px}.tip{font:9px 'DM Mono',monospace;color:#8f93a3;display:flex;align-items:center;gap:8px;white-space:nowrap}.tip>span{font-size:14px;color:var(--violet)}.tip b{font-weight:400;color:#d9dbe5}.tip i{font-style:normal;color:#646a7b}.mission-tag{margin-left:auto;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#757a89}.mission-tag span{color:#474c5b;margin-left:10px}.footer{height:48px;position:absolute;left:6.1vw;right:6.1vw;bottom:0;border-top:1px solid #ffffff10;display:flex;align-items:center;justify-content:space-between;color:#515665;font:8px 'DM Mono',monospace;letter-spacing:1.3px}.footer span:last-child{color:#9e7bfa;font-size:13px}.armory-screen{padding:42px 0}.section-heading{display:flex;justify-content:space-between;align-items:flex-end}.section-heading h2{font-size:43px;letter-spacing:-2.5px;margin:8px 0 0}.section-heading h2 span{color:var(--lime)}.back-btn{background:transparent;border:1px solid #ffffff25;padding:10px 15px;color:#b8bbca;font:10px 'DM Mono',monospace;letter-spacing:1px}.armory-intro{font-size:13px;color:#8e92a2;margin:16px 0 28px}.upgrade-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.upgrade-card{background:linear-gradient(145deg,#171a26,#10121a);border:1px solid #ffffff16;padding:19px;min-height:225px;position:relative;display:flex;flex-direction:column}.upgrade-icon{width:38px;height:38px;border:1px solid #d5ff3f4c;display:grid;place-items:center;color:var(--lime);font-size:19px;margin-bottom:16px}.upgrade-card h3{margin:0 0 8px;font-size:14px;letter-spacing:.2px}.upgrade-card p{color:#85899a;font-size:11px;line-height:1.5;margin:0 0 16px;flex:1}.upgrade-level{position:absolute;top:20px;right:17px;color:#787d8f;font:9px 'DM Mono',monospace}.upgrade-buy{width:100%;border:1px solid #ffffff25;background:#ffffff09;padding:10px;color:var(--lime);font:10px 'DM Mono',monospace;letter-spacing:.5px}.upgrade-buy:hover{background:#d5ff3f18}.upgrade-buy:disabled{color:#5d6170;cursor:default}.armory-footer{margin-top:23px;display:flex;justify-content:space-between;border-top:1px solid #ffffff15;padding-top:13px;color:#73788a;font:9px 'DM Mono',monospace;letter-spacing:1px}.armory-footer b{color:var(--lime)}
.game-screen{overflow:hidden;background:#0b0e16;border:1px solid #ffffff19}.game-screen:before{content:'';position:absolute;inset:0;pointer-events:none;z-index:1;background:radial-gradient(ellipse at center,#14142920 0,transparent 60%)}#gameCanvas{position:absolute;inset:0;width:100%;height:100%;display:block}.game-hud{position:absolute;z-index:3;top:18px;left:22px;right:22px;display:flex;justify-content:space-between;pointer-events:none}.hud-left{display:flex;gap:25px}.hud-stat{display:grid;gap:4px}.hud-stat small,.xp-label{font:8px 'DM Mono',monospace;letter-spacing:1.3px;color:#a0a4b4}.hud-stat strong{font:500 16px 'DM Mono',monospace}.pause-btn{pointer-events:auto;background:#111520dd;border:1px solid #ffffff25;padding:9px 13px;color:var(--lime);font:12px 'DM Mono',monospace}.pause-btn span{font-size:9px;color:#b9bbca;letter-spacing:1px;margin-left:5px}.game-progress{position:absolute;z-index:3;top:72px;left:22px;right:22px}.xp-label{display:flex;justify-content:space-between;margin-bottom:6px}.xp-label span:first-child{color:var(--lime)}.xp-track,.health-track{height:5px;background:#ffffff16;border-radius:5px;overflow:hidden}.xp-track>div{height:100%;width:0;background:linear-gradient(90deg,#9673ff,var(--lime));box-shadow:0 0 10px #d5ff3f66;transition:width .2s}.health-wrap{position:absolute;z-index:3;left:22px;top:101px;display:flex;align-items:center;gap:8px;color:#ff7392;font:12px 'DM Mono',monospace}.health-track{width:110px;height:4px}.health-track>div{height:100%;width:100%;background:#ff598f;transition:width .2s}.health-wrap strong{font-size:9px;color:#e3e3ed}.joystick{position:absolute;z-index:4;bottom:23px;left:22px;width:104px;height:104px;border:1px solid #ffffff32;background:#ffffff09;border-radius:50%;display:none;touch-action:none}.joystick:before{content:'';position:absolute;inset:15px;border:1px dashed #ffffff20;border-radius:50%}#joyKnob{position:absolute;left:50%;top:50%;width:43px;height:43px;transform:translate(-50%,-50%);border-radius:50%;background:#b49affbd;border:1px solid #e6dcff;box-shadow:0 0 18px #a887ff66}.mobile-hint{display:none;position:absolute;z-index:3;bottom:8px;left:54px;color:#ffffff70;font:8px 'DM Mono',monospace;letter-spacing:1px}.boss-alert{position:absolute;z-index:4;top:145px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#ff7b99;font:12px 'DM Mono',monospace;letter-spacing:1.2px;text-shadow:0 0 14px #ff598f66}.boss-alert span{font-size:8px;color:#f5d6e0;margin-left:8px}.game-toast{position:absolute;z-index:3;top:130px;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:1px;color:var(--lime);text-shadow:0 0 12px #d5ff3f77;white-space:nowrap;opacity:0;transition:opacity .25s}.game-toast.show{opacity:1}.overlay{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:#080a10bf;backdrop-filter:blur(8px);padding:16px}.modal-card{width:min(510px,95%);background:linear-gradient(145deg,#181a27,#10121b);border:1px solid #ffffff25;padding:30px;box-shadow:0 20px 100px #0009}.modal-card h2{font-size:38px;line-height:.92;letter-spacing:-2px;margin:13px 0}.modal-card h2 span{color:var(--lime)}.modal-card p{font-size:12px;color:#999dad;margin:0 0 22px}.wide{width:100%;padding:15px}.pause-card{max-width:390px}.pause-card .text-btn,.end-card .text-btn{display:block;margin:10px auto 0}.level-card{max-width:680px}.level-kicker{font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:var(--lime)}.level-kicker span{font-size:18px;margin-left:8px}.level-card h2{margin-bottom:7px}.level-card p{margin-bottom:20px}.choice-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.choice-card{background:#ffffff08;border:1px solid #ffffff22;padding:15px;text-align:left;min-height:160px;transition:.15s}.choice-card:hover{border-color:var(--lime);background:#d5ff3f0b;transform:translateY(-3px)}.choice-icon{font-size:24px;color:var(--lime);margin-bottom:13px}.choice-card h3{font-size:12px;margin:0 0 7px}.choice-card p{font-size:10px;line-height:1.45;margin:0;color:#969aaa}.end-card{max-width:435px}.run-summary{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid #ffffff19;border-bottom:1px solid #ffffff19;padding:15px 0;margin:20px 0;gap:8px}.run-summary div{display:grid;gap:5px}.run-summary small{font:8px 'DM Mono',monospace;color:#868b9b;letter-spacing:1px}.run-summary strong{font:15px 'DM Mono',monospace}.end-card .eyebrow{color:var(--lime)}
@keyframes rotate{to{transform:rotate(336deg)}}
